func TestNewTokenBucket_Validation(t *testing.T) {
	clock := &fakeClock{t: time.Unix(0, 0)}
	tests := []struct {
		name     string
		capacity float64
		rate     float64
		clock    Clock
		wantErr  bool
	}{
