		{"zero capacity", 0, 1, clock, true},
		{"negative capacity", -1, 1, clock, true},
		{"zero rate", 10, 0, clock, true},
		{"negative rate", 10, -1, clock, true},
		{"nil clock", 10, 1, nil, true},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			_, err := NewTokenBucket(tt.capacity, tt.rate, tt.clock)
			if (err != nil) != tt.wantErr {
				t.Fatalf("got err %v, wantErr %v", err, tt.wantErr)
			}
		})
	}
}

func TestTokenBucket_AllowN(t *testing.T) {
	tests := []struct {
		name     string
		capacity float64
		rate     float64
		advances []time.Duration
		n        int
		want     []bool
	}{
		{
			name:     "initial burst allowed",
			capacity: 5,
			rate:     1,
			advances: []time.Duration{0, 0, 0, 0, 0, 0},
			n:        1,
			want:     []bool{true, true, true, true, true, false},
		},
		{
			name:     "refill after time passes",
			capacity: 3,
			rate:     1,
			advances: []time.Duration{0, 0, 0, 0, 2 * time.Second, 0},
			n:        1,
			want:     []bool{true, true, true, false, true, true},
		},
		{
			name:     "AllowN consumes multiple tokens",
			capacity: 10,
			rate:     2,
			advances: []time.Duration{0, 0, 3 * time.Second, 0},
			n:        4,
			want:     []bool{true, false, true, false},
		},
		{
			name:     "n zero always allowed",
			capacity: 1,
			rate:     1,
			advances: []time.Duration{0, 0},
			n:        0,
			want:     []bool{true, true},
		},
		{
			name:     "tokens capped at capacity",
			capacity: 5,
			rate:     10,
			advances: []time.Duration{0, 10 * time.Second, 0, 0, 0, 0, 0, 0},
			n:        1,
			want:     []bool{true, true, true, true, true, false, false, false},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			clock := &fakeClock{t: time.Unix(0, 0)}
			tb, err := NewTokenBucket(tt.capacity, tt.rate, clock)
			if err != nil {
				t.Fatal(err)
			}
			for i, adv := range tt.advances {
				clock.Advance(adv)
				got := tb.AllowN(tt.n)
				if got != tt.want[i] {
					t.Fatalf("call %d: got %v, want %v", i, got, tt.want[i])
				}
			}
		})
	}
}

func TestTokenBucket_Concurrent(t *testing.T) {
	clock := &fakeClock{t: time.Unix(0, 0)}
	tb, _ := NewTokenBucket(100, 100, clock)
	done := make(chan bool, 200)
	for i := 0; i < 200; i++ {
		go func() { done <- tb.Allow() }()
	}
	allowed := 0
	for i := 0; i < 200; i++ {
		if <-done {
			allowed++
		}
	}
	if allowed != 100 {
		t.Fatalf("expected 100 allowed, got %d", allowed)
	}
}
