// Clock is an injectable time source for deterministic testing.
type Clock interface {
	Now() time.Time
}

// TokenBucket is a concurrency-safe token-bucket rate limiter.
type TokenBucket struct {
	mu       sync.Mutex
	capacity float64
	tokens   float64
	rate     float64 // tokens per second
	last     time.Time
	clock    Clock
}

// NewTokenBucket creates a TokenBucket. capacity must be > 0,
// rate must be > 0, and clock must not be nil.
func NewTokenBucket(capacity, rate float64, clock Clock) (*TokenBucket, error) {
	if capacity <= 0 {
		return nil, errors.New("tokenbucket: capacity must be > 0")
	}
	if rate <= 0 {
		return nil, errors.New("tokenbucket: rate must be > 0")
	}
	if clock == nil {
		return nil, errors.New("tokenbucket: clock must not be nil")
	}
	return &TokenBucket{
		capacity: capacity,
		tokens:   capacity,
		rate:     rate,
		last:     clock.Now(),
		clock:    clock,
	}, nil
}

// AllowN attempts to consume n tokens. Returns true if successful.
func (tb *TokenBucket) AllowN(n int) bool {
	if n <= 0 {
		return true
	}
	tb.mu.Lock()
	defer tb.mu.Unlock()

	now := tb.clock.Now()
	elapsed := now.Sub(tb.last).Seconds()
	tb.last = now

	tb.tokens += elapsed * tb.rate
	if tb.tokens > tb.capacity {
		tb.tokens = tb.capacity
	}

	if tb.tokens >= float64(n) {
		tb.tokens -= float64(n)
		return true
	}
	return false
}

// Allow attempts to consume a single token.
func (tb *TokenBucket) Allow() bool {
	return tb.AllowN(1)
}
